927, "time_original": "927年三月卢台乱前调军", "dynasty": "五代十国", "description": "派奉节等九指挥三千五百人由龙晊领赴卢台备契丹，不给铠仗，只以长竿旗帜分队。", "phases": [], "location_name": "邺都至卢台军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "673fcf87-03fe-58da-82a2-0072abcb8764"}, {"title": "赴卢台军途中闻孟知祥杀李严，讹言出现；抵达后乌震获擢副招讨令讹言加剧", "start_year": 927, "end_year": 927, "time_original": "927年三月部队赴卢台沿途及到后，确日未载", "dynasty": "五代十国", "description": "赴卢台军途中闻孟知祥杀李严，讹言出现；抵达后乌震获擢副招讨令讹言加剧。", "phases": [], "location_name": "赴卢台道路及卢台军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "63cba0af-b689-59a1-8e22-12155b8be184"}, {"title": "房知温怨乌震骤来代己，乌震到后尚未交印", "start_year": 927, "end_year": 927, "time_original": "927年三月壬申之前、乌到后", "dynasty": "五代十国", "description": "房知温怨乌震骤来代己，乌震到后尚未交印。", "phases": [], "location_name": "卢台军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7a62a0c3-713c-5596-9156-a88263e6536e"}, {"title": "乌震召房知温及齐州防御使到东寨", "start_year": 927, "end_year": 927, "time_original": "927年三月壬申", "dynasty": "五代十国", "description": "乌震召房知温及齐州防御使到东寨。", "phases": [], "location_name": "卢台东寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d1496f08-d221-5371-ad67-9d3f3377388a"}, {"title": "房知温诱龙晊所部在席上杀乌震，部众在营外鼓噪", "start_year": 927, "end_year": 927, "time_original": "927年三月壬申", "dynasty": "五代十国", "description": "房知温诱龙晊所部在席上杀乌震，部众在营外鼓噪。", "phases": [], "location_name": "卢台东寨及营外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ff57c1c0-ddad-5f68-b0df-8049c6ea9121"}, {"title": "安审通脱身夺舟渡河，统骑兵按甲不动", "start_year": 927, "end_year": 927, "time_original": "927年三月壬申杀震后", "dynasty": "五代十国", "description": "安审通脱身夺舟渡河，统骑兵按甲不动。", "phases": [], "location_name": "卢台河西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6fc29e4c-0921-59a9-9990-a947592eab78"}, {"title": "房知温欲出营被士卒拦辔，以收河西骑兵为说辞后登舟渡河", "start_year": 927, "end_year": 927, "time_original": "927年三月壬申杀震后", "dynasty": "五代十国", "description": "房知温欲出营被士卒拦辔，以收河西骑兵为说辞后登舟渡河。", "phases": [], "location_name": "卢台营门至河西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "aa624ac7-672a-5903-afff-fb4986e5c6e4"}, {"title": "房知温与安审通合谋攻击乱兵，乱兵向南行", "start_year": 927, "end_year": 927, "time_original": "927年三月壬申之后", "dynasty": "五代十国", "description": "房知温与安审通合谋攻击乱兵，乱兵向南行。", "phases": [], "location_name": "卢台河西及南行路线", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2ddff8b8-4ffc-5924-9700-49be245da1d8"}, {"title": "骑兵整队缓随，乱兵失色、列炬夜行并疲于荒泽", "start_year": 927, "end_year": 927, "time_original": "927年三月壬申夜及其后追击", "dynasty": "五代十国", "description": "骑兵整队缓随，乱兵失色、列炬夜行并疲于荒泽。", "phases": [], "location_name": "卢台南面荒泽", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d5cb9788-50c7-5b1c-9f67-42797a7cfac1"}, {"title": "翌晨骑兵四合击乱军，余众返故寨而安审通已焚寨，乱军溃散", "start_year": 927, "end_year": 927, "time_original": "927年三月壬申夜行后诘朝，确日未另记", "dynasty": "五代十国", "description": "翌晨骑兵四合击乱军，余众返故寨而安审通已焚寨，乱军溃散。", "phases": [], "location_name": "卢台南面及故寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f99d05d8-ae17-580d-ab85-eb4e9f39bff5"}, {"title": "范延光还到淇门闻卢台乱，发滑州兵返邺都以防逃逸乱兵", "start_year": 927, "end_year": 927, "time_original": "927年三月闻卢台乱之后", "dynasty": "五代十国", "description": "范延光还到淇门闻卢台乱，发滑州兵返邺都以防逃逸乱兵。", "phases": [], "location_name": "淇门、滑州至邺都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4729fa15-073b-51a3-977a-240356f0db85"}, {"title": "李嗣源遣李仁矩传诏安谕孟知祥及吏民，甲戌到成都", "start_year": 927, "end_year": 927, "time_original": "927年三月甲戌抵成都，派遣日未载", "dynasty": "五代十国", "description": "李嗣源遣李仁矩传诏安谕孟知祥及吏民，甲戌到成都。", "phases": [], "location_name": "后唐朝廷至成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1eb6e2d8-2680-5636-be6a-77fe484b5554"}, {"title": "刘训所部到荆南", "start_year": 927, "end_year": 927, "time_original": "927年三月甲戌之后本段，确日未载", "dynasty": "五代十国", "description": "刘训所部到荆南。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5d12c73e-a2e9-5d1b-8fff-89f50791fe77"}, {"title": "马殷遣许德勋等率水军屯岳州", "start_year": 927, "end_year": 927, "time_original": "927年三月荆南役本段，确日未载", "dynasty": "五代十国", "description": "马殷遣许德勋等率水军屯岳州。", "phases": [], "location_name": "岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "47864adc-79d4-551e-a4b7-630c85ccc04f"}, {"title": "荆南坚壁不战，向吴求救", "start_year": 927, "end_year": 927, "time_original": "927年三月荆南役，确日未载", "dynasty": "五代十国", "description": "荆南坚壁不战，向吴求救。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precisi